import{z as i,x as n,o as A,c as s,q as e,j as l,D as a,d as t,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"隐私与本地化","description":"","frontmatter":{"title":"隐私与本地化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/edge-privacy-localization.md","filePath":"llm/edge-privacy-localization.md","lastUpdated":1791413859000}'),d={name:"llm/edge-privacy-localization.md"};function p(C,E,D,c,m,F){const B=n("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="隐私与本地化" tabindex="-1">隐私与本地化 <a class="header-anchor" href="#隐私与本地化" aria-label="Permalink to &quot;隐私与本地化&quot;">​</a></h1><div class="epigraph"><p>本地化的价值不是端侧更快，是有些上下文只有本地能合法地读：先给数据分级，再谈模型放哪。</p><footer>—— 据 GDPR 数据最小化原则与 Apple Private Cloud Compute, 2024 架构文档整理</footer></div><p><a href="/llm/edge-cloud-collaboration">上一课</a>把路由、升级与降级铺成系统，但路由表里还少一列：数据等级。邮件、消息、照片、健康记录这类上下文，用户与法规都不愿其原文离开设备；而「全部本地」既不现实——端侧模型能力有上限——也不必要，多数请求并不携带敏感上下文。本课写隐私如何反过来决定架构：数据分几级、每级配什么技术件、「云可用但不可保留」怎么工程化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分级表四行。L1：原文敏感——本地推理、本地索引、本地检索，原文不出进程。L2：脱敏后可用——本地识别实体并替换成占位符，把模板送云，回复再把实体回填。L3：非敏感——按上一课的路由自由派云。L4：原文可上云但不可保留——由云侧架构承诺。威胁模型要先写清：这一套防的是网络窃听、服务方保留与二次利用，防不了已越狱设备上的恶意应用与物理接触，超出部分是系统安全课的题。<span class="marginnote">威胁模型就是「先想清楚防谁」：列出可能的攻击者（偷听网络的人、会保留数据的服务商、你手机里的恶意应用）和各自的本事，再检查方案挡得住哪几个。说清防谁、不防谁不是给自己留后门，而是让读者知道这套方案的有效边界画在哪里。</span>分级表的典型错误形态是把「脱敏」当万能：上下文一丰富，占位符周围的线索足以重识别，L2 就悄悄失效了。</p><h3 id="l2-的边界" tabindex="-1">L2 的边界 <a class="header-anchor" href="#l2-的边界" aria-label="Permalink to &quot;L2 的边界&quot;">​</a></h3><p>脱敏可信的前提是「单点实体、无交叉上下文」：替换一个手机号是安全的；替换一段病历叙述里的多处实体，残缺信息仍可能拼回。所以 L2 的规则要保守：只对模板化、结构性强的文本开放；自由文本降级为 L1 或 L4，不硬走脱敏。</p>',7)),(A(),l(o,null,{default:a(()=>[r(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E8%AF%B7%E6%B1%82%E6%90%BA%E5%B8%A6%E7%9A%84%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%20--%3E%20G%7B%22%E6%95%B0%E6%8D%AE%E7%AD%89%E7%BA%A7%22%7D%0A%20%20G%20--%3E%7C%22L1%20%E6%95%8F%E6%84%9F%E5%8E%9F%E6%96%87%22%7C%20L%5B%22%E6%9C%AC%E5%9C%B0%E6%8E%A8%E7%90%86%E4%B8%8E%E6%9C%AC%E5%9C%B0%E6%A3%80%E7%B4%A2%22%5D%0A%20%20G%20--%3E%7C%22L2%20%E5%8F%AF%E8%84%B1%E6%95%8F%22%7C%20M%5B%22%E6%9C%AC%E5%9C%B0%E6%9B%BF%E6%8D%A2%E5%AE%9E%E4%BD%93%E9%80%81%E6%A8%A1%E6%9D%BF%22%5D%0A%20%20G%20--%3E%7C%22L3%20%E9%9D%9E%E6%95%8F%E6%84%9F%22%7C%20C%5B%22%E6%8C%89%E8%B7%AF%E7%94%B1%E6%B4%BE%E4%BA%91%22%5D%0A%20%20G%20--%3E%7C%22L4%20%E5%8F%AF%E7%94%A8%E4%B8%8D%E5%8F%AF%E7%95%99%22%7C%20P%5B%22%E6%97%A0%E7%8A%B6%E6%80%81%E4%BA%91%3A%20%E5%8F%AF%E9%AA%8C%E8%AF%81%E4%B8%8D%E4%BF%9D%E7%95%99%22%5D%0A%20%20M%20--%3E%20B%5B%22%E5%9B%9E%E5%A4%8D%E5%9B%9E%E5%A1%AB%E5%AE%9E%E4%BD%93%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>技术件按等级配。L1：检索留端、KV 不出设备、会话历史只落本地存储。L2：实体识别与占位符表都在端上保管，回填之后才进会话历史，云端只见模板。L3：走通用路由，无额外件。L4：云侧做无状态推理——请求处理完即丢、不接持久存储、镜像可被第三方核验；Apple Private Cloud Compute 的公开架构是这一级的工程参照：本地不可行时上云，但云侧承诺不保留且承诺可验证。通用件两件：遥测脱敏，报延迟与计数、不报内容；日志审计——crash 报告与性能日志是最常见的 prompt 泄漏通道，把提示与生成文本从日志面排除，是本地化改造里收益最大的一步。<span class="marginnote">看一个重识别的例子：把「张三在协和医院看甲状腺」脱敏成「[人名]在[地点]看[疾病]」，云端确实看不到实体，但「甲状腺专科只有少数几家医院」这类背景知识仍可能反推出答案——占位符挡住了原文，挡不住线索周围的推断，所以自由文本宁可降级，不硬脱敏。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么分级先行而不是架构先行：哪些组件放在端上，决定这一代产品的能力上限，改架构的成本远高于改路由；法规与用户预期会变，新等级出现时应当改路由表与配置，而不是搬组件。所以把数据等级做成路由器的一等信号，与设备档位、电量、RTT 并列——上一课的信号快照加一列。L4 的机理是「可验证的无状态」：无状态使保留在技术上不可行而非政策上不允许，可验证让承诺可审计；这两点把「我们承诺不保留」从一句文案变成一条可以验的属性。</p>',4)),(A(),l(o,null,{default:a(()=>[r(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%AB%AF%E4%B8%8A%E6%8B%BF%E5%88%B0%E5%8E%9F%E6%96%87%22%5D%20--%3E%20N%7B%22%E5%AE%9E%E4%BD%93%E5%BD%A2%E6%80%81%3F%22%7D%0A%20%20N%20--%3E%7C%22%E5%8D%95%E7%82%B9%E5%AE%9E%E4%BD%93%3A%20%E7%94%B5%E8%AF%9D%20%E9%82%AE%E7%AE%B1%20%E5%8D%A1%E5%8F%B7%22%7C%20R%5B%22%E6%9B%BF%E6%8D%A2%E4%B8%BA%E5%8D%A0%E4%BD%8D%E7%AC%A6%22%5D%0A%20%20N%20--%3E%7C%22%E8%87%AA%E7%94%B1%E6%96%87%E6%9C%AC%3A%20%E7%97%85%E5%8E%86%E5%8F%99%E8%BF%B0%20%E6%97%A5%E8%AE%B0%22%7C%20F%5B%22%E9%99%8D%E7%BA%A7%3A%20%E6%8C%89%20L1%20%E7%95%99%E7%AB%AF%3Cbr%2F%3E%E6%88%96%E6%8C%89%20L4%20%E8%B5%B0%E6%97%A0%E7%8A%B6%E6%80%81%E4%BA%91%22%5D%0A%20%20R%20--%3E%20K%7B%22%E5%8D%A0%E4%BD%8D%E7%AC%A6%E5%91%A8%E5%9B%B4%E7%BA%BF%E7%B4%A2%E4%B8%B0%E5%AF%8C%3F%22%7D%0A%20%20K%20--%3E%7C%22%E5%90%A6%3A%20%E6%A8%A1%E6%9D%BF%E5%8C%96%20%E7%BB%93%E6%9E%84%E6%80%A7%E5%BC%BA%22%7C%20S%5B%22%E6%A8%A1%E6%9D%BF%E9%80%81%E4%BA%91%20%E5%9B%9E%E5%A4%8D%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20K%20--%3E%7C%22%E6%98%AF%3A%20%E4%B8%8A%E4%B8%8B%E6%96%87%E8%83%BD%E6%8B%BC%E5%9B%9E%22%7C%20RI%5B%22%E9%87%8D%E8%AF%86%E5%88%AB%E9%A3%8E%E9%99%A9%3A%20L2%20%E5%A4%B1%E6%95%88%20%E5%BF%85%E9%A1%BB%E9%99%8D%E7%BA%A7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">检查泄漏通道时按数据流走一遍：prompt、检索原文、生成文本各自出现在哪些日志、缓存与上报里——端侧推理省下的隐私，常被一行 crash 日志送出去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写端侧训练与联邦学习；不给合规结论，法律判断不在工程课范围内；PCC 的密码学证明细节超出本课，只取架构口径。L2 的重识别风险随模型能力上升而变大，规则要定期复评。跨区域的数据出境要求按区域配置，放进路由的静态规则层，不放动态信号层。<span class="marginnote">为什么强调「L2 规则要定期复评」：脱敏的安全性不是常量，随对手能力浮动。云端模型越强，能从越少的线索里拼出实体——今天判定安全的模板，两年后更强的模型可能拼回原文。所以分级表要当活文档，随模型换代重审，而不是一次定终身。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据分四级：敏感原文留端、脱敏模板、非敏感上云、可用不可留。</li><li>L2 只对单点实体与模板化文本可信，自由文本降级处理。</li><li>L4 的工程口径是无状态加可验证，PCC 是公开参照。</li><li>遥测与 crash 日志是最大泄漏通道，先封它再谈架构。</li><li>出处：GDPR 数据最小化原则；Apple Private Cloud Compute, 2024 架构文档；按本课程口径整理。</li></ul>',5))])}const u=i(d,[["render",p]]);export{h as __pageData,u as default};
